{"id":"385855ee1687","name":"Wikipedia Solar System","dark":true,"bg":"#02040a","surface":"#070c1b","surface2":"#0d1b3a","fg":"#e2e8f0","ink":"#00f0ff","accent":"#00f0ff","remapSurfaces":false,"customCss":"html body { background: radial-gradient(circle at center, #070c1b 0%, #02040a 100%) !important; color: #e2e8f0 !important; padding: 70px 16px 120px !important; overflow-x: hidden !important; } html body [data-mydes="header"] { background: rgba(7, 12, 27, 0.8) !important; backdrop-filter: blur(10px) !important; border-bottom: 1px solid rgba(0, 240, 255, 0.3) !important; border-radius: 16px !important; padding: 12px !important; margin-bottom: 24px !important; } html body [data-mydes="search"] { background: rgba(13, 27, 58, 0.9) !important; border: 1px solid #00f0ff !important; border-radius: 30px !important; box-shadow: 0 0 20px rgba(0, 240, 255, 0.2) !important; padding: 8px 16px !important; } html body [data-mydes="grid"] { display: grid !important; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)) !important; gap: 16px !important; perspective: 1000px !important; padding: 10px !important; } html body [data-mydes="card"] { transform: perspective(800px) rotateX(var(--m-rx, 3deg)) rotateY(var(--m-ry, -3deg)) translateZ(10px) !important; backdrop-filter: blur(12px) !important; background: rgba(10, 25, 48, 0.75) !important; border: 1px solid rgba(0, 240, 255, 0.4) !important; border-radius: 20px !important; box-shadow: 0 0 20px rgba(0, 240, 255, 0.15), inset 0 0 10px rgba(0, 240, 255, 0.05) !important; padding: 18px !important; text-align: center !important; transition: transform 0.3s ease !important; } html body [data-mydes="card"]:hover { transform: perspective(800px) rotateX(0deg) rotateY(0deg) translateZ(25px) !important; border-color: #00f0ff !important; box-shadow: 0 0 30px rgba(0, 240, 255, 0.4) !important; } html body [data-mydes="title"], html body [data-mydes="heading"] { color: #00f0ff !important; font-weight: 700 !important; text-shadow: 0 0 8px rgba(0, 240, 255, 0.5) !important; } html body [data-mydes="btn"] { background: linear-gradient(135deg, #00f0ff 0%, #0077ff 100%) !important; color: #02040a !important; border-radius: 24px !important; font-weight: 800 !important; border: none !important; box-shadow: 0 0 15px rgba(0, 240, 255, 0.4) !important; padding: 12px 24px !important; }","backdropHtml":"<div style="position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden;"><svg style="position:absolute;width:100%;height:100%;opacity:0.25;" viewBox="0 0 1000 1000"><circle cx="500" cy="500" r="420" fill="none" stroke="#00f0ff" stroke-width="1" stroke-dasharray="4 8" /><circle cx="500" cy="500" r="320" fill="none" stroke="#00f0ff" stroke-width="1" stroke-dasharray="6 12" /><circle cx="500" cy="500" r="220" fill="none" stroke="#00f0ff" stroke-width="1" stroke-dasharray="2 6" /><circle cx="500" cy="500" r="90" fill="none" stroke="#00f0ff" stroke-width="1.5" /></svg><canvas id="spaceCanvas" style="position:absolute;inset:0;width:100%;height:100%;"></canvas></div>","hudHtml":"<div style="position:fixed;bottom:16px;left:16px;right:16px;z-index:2147483640;display:flex;gap:12px;justify-content:space-around;background:rgba(7,12,27,0.85);backdrop-filter:blur(16px);border:1px solid rgba(0,240,255,0.4);border-radius:24px;padding:12px;box-shadow:0 10px 30px rgba(0,0,0,0.8), 0 0 20px rgba(0,240,255,0.2);"><button onclick="MydesBridge.focusSearch()" style="flex:1;background:rgba(13,27,58,0.9);border:1px solid #00f0ff;color:#00f0ff;padding:12px;border-radius:16px;font-weight:700;font-size:13px;display:flex;flex-direction:column;align-items:center;gap:4px;box-shadow:0 0 10px rgba(0,240,255,0.2);cursor:pointer;"><span style="font-size:18px;">🪐</span>Explore Search</button><button onclick="MydesBridge.speakPage()" style="flex:1;background:rgba(13,27,58,0.9);border:1px solid #00f0ff;color:#00f0ff;padding:12px;border-radius:16px;font-weight:700;font-size:13px;display:flex;flex-direction:column;align-items:center;gap:4px;box-shadow:0 0 10px rgba(0,240,255,0.2);cursor:pointer;"><span style="font-size:18px;">📡</span>Audio Comms</button><button onclick="MydesBridge.zoom(0.15)" style="flex:1;background:rgba(13,27,58,0.9);border:1px solid #00f0ff;color:#00f0ff;padding:12px;border-radius:16px;font-weight:700;font-size:13px;display:flex;flex-direction:column;align-items:center;gap:4px;box-shadow:0 0 10px rgba(0,240,255,0.2);cursor:pointer;"><span style="font-size:18px;">🔭</span>Magnify</button></div>","customJs":"MydesBridge.enable3DTilt(1.0);
const canvas = document.getElementById('spaceCanvas');
if (canvas) {
 const ctx = canvas.getContext('2d');
 let w = canvas.width = window.innerWidth;
 let h = canvas.height = window.innerHeight;
 window.addEventListener('resize', () => {
 w = canvas.width = window.innerWidth;
 h = canvas.height = window.innerHeight;
 });
 const stars = Array.from({ length: 120 }, () => ({
 x: Math.random() * w,
 y: Math.random() * h,
 size: Math.random() * 2,
 alpha: Math.random(),
 speed: Math.random() * 0.05 + 0.01
 }));
 function animate() {
 ctx.clearRect(0, 0, w, h);
 stars.forEach(s => {
 s.alpha += s.speed;
 if (s.alpha > 1 || s.alpha < 0) s.speed = -s.speed;
 ctx.fillStyle = `rgba(255, 255, 255, ${Math.abs(s.alpha)})`;
 ctx.beginPath();
 ctx.arc(s.x, s.y, s.size, 0, Math.PI * 2);
 ctx.fill();
 });
 requestAnimationFrame(animate);
 }
 animate();
}"}

{"id":"6224031b8a53","name":"Solar System Wikipedia","dark":true,"bg":"#020208","surface":"#0a0c1b","surface2":"#121733","fg":"#e2e8f0","ink":"#ffffff","accent":"#ffaa00","remapSurfaces":false,"customCss":"html body { background: transparent !important; color: #e2e8f0 !important; font-family: 'Space Grotesk', system-ui, sans-serif !important; padding: 70px 16px 120px !important; overflow-x: hidden !important; } html body [data-mydes="header"] { background: rgba(5, 7, 20, 0.85) !important; backdrop-filter: blur(16px) !important; border-bottom: 1px solid rgba(255, 170, 0, 0.3) !important; position: fixed !important; top: 0 !important; left: 0 !important; right: 0 !important; z-index: 100 !important; padding: 12px 16px !important; } html body [data-mydes="search"] input, html body [data-mydes="field"] { background: rgba(15, 22, 50, 0.9) !important; border: 1px solid #ffaa00 !important; color: #fff !important; border-radius: 24px !important; padding: 10px 18px !important; } html body [data-mydes="main"] { position: relative !important; z-index: 2 !important; } html body [data-mydes="grid"] { perspective: 1200px !important; display: grid !important; gap: 20px !important; } html body [data-mydes="card"] { transform: perspective(1000px) rotateX(var(--m-rx, 2deg)) rotateY(var(--m-ry, -2deg)) translateZ(10px) !important; backdrop-filter: blur(14px) !important; background: rgba(10, 15, 35, 0.78) !important; border: 1px solid rgba(255, 170, 0, 0.4) !important; border-radius: 20px !important; padding: 20px !important; box-shadow: 0 0 30px rgba(255, 170, 0, 0.15), inset 0 0 15px rgba(255, 170, 0, 0.05) !important; transition: transform 0.2s ease, border-color 0.2s ease !important; } html body [data-mydes="card"]:hover { border-color: #ffaa00 !important; box-shadow: 0 0 40px rgba(255, 170, 0, 0.3), inset 0 0 20px rgba(255, 170, 0, 0.1) !important; } html body [data-mydes="title"], html body [data-mydes="heading"] { color: #ffcc44 !important; font-weight: 700 !important; text-shadow: 0 0 10px rgba(255, 204, 68, 0.4) !important; } html body [data-mydes="btn"] { background: linear-gradient(135deg, #ffaa00, #ff5500) !important; border: none !important; color: #000 !important; font-weight: 800 !important; border-radius: 20px !important; padding: 10px 20px !important; box-shadow: 0 0 15px rgba(255, 170, 0, 0.4) !important; } html body [data-mydes="media"] { border-radius: 12px !important; border: 1px solid rgba(255, 170, 0, 0.3) !important; }","backdropHtml":"<div style="position:absolute; inset:0; background: radial-gradient(circle at 50% 30%, #101432 0%, #020208 70%); overflow:hidden; pointer-events:none;"><canvas id="spaceCanvas" style="position:absolute; inset:0; width:100%; height:100%;"></canvas><div style="position:absolute; top: 15vh; left: 10vw; width: 120px; height: 120px; background: radial-gradient(circle, #ffcc00 0%, #ff4500 60%, transparent 100%); border-radius: 50%; box-shadow: 0 0 80px #ffaa00, 0 0 150px #ff4500; filter: blur(1px); opacity: 0.85;"></div><div style="position:absolute; top: 35vh; right: 8vw; width: 70px; height: 70px; background: radial-gradient(circle, #3b82f6 0%, #1e3a8a 70%, transparent 100%); border-radius: 50%; box-shadow: 0 0 40px #3b82f6; opacity: 0.7;"></div><div style="position:absolute; bottom: 20vh; left: 15vw; width: 90px; height: 90px; background: radial-gradient(circle, #ef4444 0%, #7f1d1d 70%, transparent 100%); border-radius: 50%; box-shadow: 0 0 50px #ef4444; opacity: 0.65;"></div></div>","hudHtml":"<div style="position:fixed; bottom:0; left:0; right:0; background:rgba(5, 7, 20, 0.9); backdrop-filter:blur(16px); border-top:1px solid rgba(255,170,0,0.3); padding:12px 20px; display:flex; justify-content:space-around; align-items:center; z-index:2147483640;"><button onclick="MydesBridge.focusSearch()" style="background:rgba(255,170,0,0.15); border:1px solid #ffaa00; color:#ffaa00; padding:10px 16px; border-radius:16px; font-weight:700; font-size:0.9rem; cursor:pointer;">🔭 Search Cosmos</button><button onclick="MydesBridge.speakPage()" style="background:rgba(255,170,0,0.15); border:1px solid #ffaa00; color:#ffaa00; padding:10px 16px; border-radius:16px; font-weight:700; font-size:0.9rem; cursor:pointer;">📡 Audio Comms</button><button onclick="window.scrollTo({top:0, behavior:'smooth'})" style="background:rgba(255,170,0,0.15); border:1px solid #ffaa00; color:#ffaa00; padding:10px 16px; border-radius:16px; font-weight:700; font-size:0.9rem; cursor:pointer;">🚀 Orbit Top</button></div>","customJs":"MydesBridge.enable3DTilt(1.0);
const canvas = document.getElementById('spaceCanvas');
if (canvas) {
 const ctx = canvas.getContext('2d');
 let w = canvas.width = window.innerWidth;
 let h = canvas.height = window.innerHeight;
 window.addEventListener('resize', () => {
 w = canvas.width = window.innerWidth;
 h = canvas.height = window.innerHeight;
 });
 const stars = Array.from({length: 120}, () => ({
 x: Math.random() * w,
 y: Math.random() * h,
 size: Math.random() * 2 + 0.5,
 alpha: Math.random(),
 speed: Math.random() * 0.05 + 0.01
 }));
 function animate() {
 ctx.clearRect(0, 0, w, h);
 ctx.fillStyle = '#ffffff';
 stars.forEach(s => {
 s.alpha += s.speed;
 if (s.alpha > 1 || s.alpha < 0.2) s.speed = -s.speed;
 ctx.globalAlpha = Math.abs(s.alpha);
 ctx.beginPath();
 ctx.arc(s.x, s.y, s.size, 0, Math.PI * 2);
 ctx.fill();
 });
 requestAnimationFrame(animate);
 }
 animate();
}"}
